mapper.select:
SELECT
    EXISTS(
        SELECT 1
        FROM blog_article_like
        WHERE article_id = #{article}
          AND user_id = #{user}
    ) AS liked,
    (
        SELECT COUNT(*)
        FROM blog_article_like
        WHERE article_id = #{article}
    ) AS like_count

mapper.delete:
DELETE FROM blog_article_like
WHERE article_id = #{article}
  AND user_id = #{user}
